//! All151 scalar-name comparison sites in82BDA0D0, in native search order.
//! Raw disassembly corrects the old130-entry catalog: direct-name checks were
//! omitted, Spin was misidentified, and left/right grab calls were conflated.
use super::name::encode;
use crate::animation::output::attributes::AttributeName;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct ScalarAttribute {
    pub name: &'static str,
    pub encoded_name: AttributeName,
    /// Traceability only, never an executable/data address in the host.
    pub comparison_site: u32,
}
const fn entry(name: &'static str, comparison_site: u32) -> ScalarAttribute {
    ScalarAttribute {
        name,
        encoded_name: encode(name.as_bytes()),
        comparison_site,
    }
}
